66	// Tablet/desktop pages live in their own lazy chunks. Keep these as direct
67	// imports (rather than an eager barrel) so phones never download the second UI.
68	// The chrome is lazy for the same reason: it is mounted once above the router,
69	// but a static import would put the frame, shell, canvas and desktop.css in the
70	// entry chunk that phones also load.
71	const DesktopChrome           = lazy(() => import("@/desktop/DesktopChrome"));
72	
73	/**
74	 * Suspense fallback for the desktop chrome and its page slot. Deliberately
75	 * empty: a lazy chunk resolving must never paint a spinner over chrome that is
76	 * already on screen — the incoming page's own cascade is the only motion the
77	 * user should see. Defined here rather than imported, so that reaching for the
78	 * fallback does not drag the desktop chunk into the entry bundle.
79	 *
80	 * Being empty makes it invisible to a probe watching for painted loaders, so it
81	 * carries a `data-testid` instead: a suspended page slot is worth *reporting*
82	 * (the chrome held, the page area went briefly blank) without failing a run, and
83	 * that is only distinguishable from a real flash if it can be seen.
84	 */
85	function DesktopPageFallback() {
86	  return <div data-testid="desktop-page-fallback" className="tapt-desktop-page-fallback" aria-hidden="true" />;
87	}
