89	const DesktopRetailHome       = lazy(() => import("@/desktop/pages/retail-home"));
90	const DesktopRetailStock      = lazy(() => import("@/desktop/pages/retail-stock"));
91	const DesktopRetailTerminal   = lazy(() => import("@/desktop/pages/retail-terminal"));
92	const DesktopRetailAnalytics  = lazy(() => import("@/desktop/pages/retail-analytics"));
93	const DesktopRetailSettings   = lazy(() => import("@/desktop/pages/retail-settings"));
94	const DesktopPropertyHome      = lazy(() => import("@/desktop/pages/property-home"));
95	const DesktopPropertyClients   = lazy(() => import("@/desktop/pages/property-clients"));
96	const DesktopPropertyTerminal  = lazy(() => import("@/desktop/pages/property-terminal"));
97	const DesktopPropertyAnalytics = lazy(() => import("@/desktop/pages/property-analytics"));
98	const DesktopPropertySettings  = lazy(() => import("@/desktop/pages/property-settings"));
99	const DesktopTradesHome         = lazy(() => import("@/desktop/pages/trades-home"));
100	const DesktopTradesClients      = lazy(() => import("@/desktop/pages/trades-clients"));
101	const DesktopTradesTerminal     = lazy(() => import("@/desktop/pages/trades-terminal"));
102	const DesktopTradesAnalytics    = lazy(() => import("@/desktop/pages/trades-analytics"));
103	const DesktopTradesSettings     = lazy(() => import("@/desktop/pages/trades-settings"));
104	const DesktopLegacyPage         = lazy(() => import("@/desktop/DesktopLegacyPage"));
105	
106	/* Route chunks a signed-in merchant navigates between. Warmed one at a time
107	   during browser idle after first paint, so by the time they tap the dock the
108	   chunk is already cached and Suspense never shows the full-screen loader —
109	   the framer-motion page transition runs back-to-back instead. Vite dedupes
110	   these import() calls with the lazy() ones above (same module = same chunk).
111	   Ordered by likelihood of being the next tap. */
112	const MOBILE_PRELOAD_ROUTES: Array<() => Promise<unknown>> = [
113	  () => import("@/pages/dashboard"),
114	  () => import("@/pages/merchant-terminal-mobile-v2"),
115	  () => import("@/pages/transactions"),
116	  () => import("@/pages/stock-management"),
117	  () => import("@/pages/settings"),
118	  () => import("@/pages/property/property-dashboard"),
119	  () => import("@/pages/property/tenant-directory"),
120	  () => import("@/pages/property/property-analytics"),
121	  () => import("@/pages/property/property-terminal"),
122	  () => import("@/pages/property/tenant-profile"),
123	  () => import("@/pages/trades/trades-dashboard"),
124	  () => import("@/pages/trades/client-directory"),
125	  () => import("@/pages/trades/trades-analytics"),
126	  () => import("@/pages/trades/trades-terminal"),
127	  () => import("@/pages/trades/client-profile"),
128	  () => import("@/pages/trades/quote-builder"),
129	  () => import("@/pages/trades/recurring-schedules"),
130	  () => import("@/pages/payment-stack"),
131	  () => import("@/pages/nfc-payment"),
132	];
133	
134	const DESKTOP_PRELOAD_ROUTES: Array<() => Promise<unknown>> = [
135	  () => import("@/desktop/pages/retail-home"),
136	  () => import("@/desktop/pages/retail-stock"),
137	  () => import("@/desktop/pages/retail-terminal"),
138	  () => import("@/desktop/pages/retail-analytics"),
139	  () => import("@/desktop/pages/retail-settings"),
140	  () => import("@/desktop/pages/property-home"),
141	  () => import("@/desktop/pages/property-clients"),
142	  () => import("@/desktop/pages/property-terminal"),
143	  () => import("@/desktop/pages/property-analytics"),
144	  () => import("@/desktop/pages/property-settings"),
145	  () => import("@/desktop/pages/trades-home"),
146	  () => import("@/desktop/pages/trades-clients"),
147	  () => import("@/desktop/pages/trades-terminal"),
148	  () => import("@/desktop/pages/trades-analytics"),
149	  () => import("@/desktop/pages/trades-settings"),
150	  () => import("@/desktop/DesktopLegacyPage"),
151	];
