153	/* Sequential (not Promise.all) so warming never competes with the page's own
154	   data fetches for bandwidth; each chunk waits for the next idle slice. */
155	function useRoutePreload(enabled: boolean, deviceClass: DeviceClass) {
156	  useEffect(() => {
157	    if (!enabled) return;
158	    const routes = deviceClass === "mobile" ? MOBILE_PRELOAD_ROUTES : DESKTOP_PRELOAD_ROUTES;
159	    let stopped = false;
160	    let i = 0;
161	    const idle = (cb: () => void) =>
162	      "requestIdleCallback" in window
163	        ? (window as any).requestIdleCallback(cb, { timeout: 2000 })
164	        : setTimeout(cb, 250);
165	    const next = () => {
166	      if (stopped || i >= routes.length) return;
167	      routes[i++]()
168	        .catch(() => {}) // offline / chunk 404 — the lazy() route will surface it if actually visited
169	        .finally(() => idle(next));
170	    };
171	    // Head start for first paint + the auth check before saturating the pipe.
172	    const t = setTimeout(() => idle(next), 1000);
173	    return () => { stopped = true; clearTimeout(t); };
174	  }, [deviceClass, enabled]);
175	}
176	
177	/**
178	 * The route-level full-screen loader, for mobile and public routes.
179	 *
180	 * `data-testid` marks it as exactly that: the transition probes gate on this
181	 * element appearing, and must not confuse it with a page's own content spinner,
182	 * which shares the `animate-spin` utility class but covers nothing.
183	 */
184	function PageLoader() {
185	  return (
186	    <div data-testid="page-loader" className="min-h-screen flex items-center justify-center" style={{ background: "#060D1F" }}>
187	      <div className="w-8 h-8 border-2 border-[#00DFC8] border-t-transparent rounded-full animate-spin" />
188	    </div>
189	  );
190	}
191	
192	// Auth is checked ONCE at app load and cached here. ProtectedRoute reads from
193	// this context so navigating between protected routes never shows a loader or
194	// makes a redundant API call — both of which would destroy page transitions.
195	type AuthData = {
196	  isAuthenticated: boolean;
197	  merchantId?: string | null;
198	  role?: string | null;
199	  onboardingCompleted?: boolean | null;
200	  gstRegistered?: boolean;
201	  tradeGstMode?: "inclusive" | "exclusive";
202	};
203	
204	const AuthContext = createContext<{ auth: AuthData | null; isChecking: boolean }>({
205	  auth: null,
206	  isChecking: true,
207	});
208	
209	function AuthProvider({ children }: { children: React.ReactNode }) {
210	  const [auth, setAuth] = useState<AuthData | null>(null);
211	  const [isChecking, setIsChecking] = useState(true);
212	
213	  useEffect(() => {
214	    const token = localStorage.getItem("authToken");
215	    if (!token) {
216	      setAuth({ isAuthenticated: false });
217	      setIsChecking(false);
218	      return;
219	    }
220	    fetch('/api/auth/me', { headers: { Authorization: `Bearer ${token}` } })
221	      .then(async r => {
222	        if (r.ok) {
223	          const data = await r.json();
224	          setAuth({
225	            isAuthenticated: true,
226	            merchantId: data?.user?.merchantId ?? null,
227	            role: data?.user?.role ?? null,
228	            onboardingCompleted: data?.user?.onboardingCompleted ?? null,
229	            gstRegistered: data?.user?.gstRegistered ?? false,
230	            tradeGstMode: data?.user?.tradeGstMode === "exclusive" ? "exclusive" : "inclusive",
231	          });
232	        } else {
233	          localStorage.removeItem("authToken");
234	          localStorage.removeItem("user");
235	          localStorage.removeItem("merchantId");
236	          setAuth({ isAuthenticated: false });
237	        }
238	      })
239	      .catch(() => {
240	        localStorage.removeItem("authToken");
241	        localStorage.removeItem("user");
242	        localStorage.removeItem("merchantId");
243	        setAuth({ isAuthenticated: false });
244	      })
245	      .finally(() => setIsChecking(false));
246	  }, []);
247	
248	  return <AuthContext.Provider value={{ auth, isChecking }}>{children}</AuthContext.Provider>;
249	}
250	
251	function ProtectedRoute({ children, skipOnboardingCheck = false, tutorialPage }: {
252	  children: React.ReactNode;
253	  skipOnboardingCheck?: boolean;
254	  tutorialPage?: TutorialPageKey;
255	}) {
256	  const [, setLocation] = useLocation();
257	  const { auth, isChecking } = useContext(AuthContext);
258	
259	  useEffect(() => {
260	    if (isChecking || !auth) return;
261	    if (!auth.isAuthenticated) {
262	      const returnTo = encodeURIComponent(window.location.pathname + window.location.search);
263	      setLocation(`/login?returnTo=${returnTo}`);
264	      return;
265	    }
266	    if (
267	      !skipOnboardingCheck &&
268	      auth.merchantId &&
269	      auth.role !== 'admin' &&
270	      auth.onboardingCompleted === false
271	    ) {
272	      setLocation("/onboarding");
273	    }
274	  }, [isChecking, auth, skipOnboardingCheck, setLocation]);
275	
276	  if (isChecking) return <PageLoader />;
277	  if (!auth?.isAuthenticated) return null;
278	  if (!skipOnboardingCheck && auth.merchantId && auth.role !== 'admin' && auth.onboardingCompleted === false) return null;
279	
280	  return tutorialPage
281	    ? <TutorialPageBoundary pageKey={tutorialPage}>{children}</TutorialPageBoundary>
282	    : <>{children}</>;
283	}
284	
285	function AdminProtectedRoute({ children }: { children: React.ReactNode }) {
286	  const [isAuthenticated, setIsAuthenticated] = useState(false);
287	  const [isChecking, setIsChecking] = useState(true);
288	
289	  useEffect(() => {
290	    const checkAdminAuth = async () => {
291	      const token = localStorage.getItem("adminAuthToken");
292	      if (!token) {
293	        setIsAuthenticated(false);
294	        setIsChecking(false);
295	        window.location.href = "/login";
296	        return;
297	      }
298	      try {
299	        const response = await fetch("/api/admin/auth/me", {
300	          headers: { Authorization: `Bearer ${token}` },
301	        });
302	        if (response.ok) {
303	          setIsAuthenticated(true);
304	        } else {
305	          localStorage.removeItem("adminAuthToken");
306	          localStorage.removeItem("adminUser");
307	          setIsAuthenticated(false);
308	          window.location.href = "/login";
309	        }
310	      } catch (error) {
311	        localStorage.removeItem("adminAuthToken");
312	        localStorage.removeItem("adminUser");
313	        setIsAuthenticated(false);
314	        window.location.href = "/login";
315	      }
316	      setIsChecking(false);
317	    };
318	    checkAdminAuth();
319	  }, []);
320	
321	  if (isChecking) return <PageLoader />;
322	  return isAuthenticated ? <>{children}</> : null;
323	}
324	
325	function GA4PageTracker() {
326	  const [location] = useLocation();
327	  useEffect(() => {
328	    if (typeof window !== 'undefined' && (window as any).gtag) {
329	      (window as any).gtag('event', 'page_view', {
330	        page_path: redactCustomerPaymentAddress(location),
331	        page_title: document.title,
332	      });
333	    }
334	  }, [location]);
335	  return null;
336	}
337	
338	function isPwaStandalone() {
339	  return (
340	    window.matchMedia('(display-mode: standalone)').matches ||
341	    (window.navigator as any).standalone === true
342	  );
343	}
344	
345	type MerchantMode = "retail" | "property" | "trades";
346	
347	const RETAIL_MODE_PATHS = new Set(["/dashboard", "/stock", "/terminal", "/transactions"]);
348	
349	function merchantModeForLocation(location: string): MerchantMode {
350	  if (location.startsWith("/property")) return "property";
351	  if (location.startsWith("/trades")) return "trades";
352	  if (RETAIL_MODE_PATHS.has(location)) return "retail";
353	  try {
354	    const stored = localStorage.getItem("taptMode");
355	    if (stored === "property" || stored === "trades" || stored === "retail") return stored;
356	  } catch {
357	    // Storage can be unavailable in privacy-restricted browser contexts.
358	  }
359	  return "retail";
360	}
361	
362	function Router({ deviceClass }: { deviceClass: DeviceClass }) {
363	  const [location] = useLocation();
364	  const merchantMode = merchantModeForLocation(location);
365	
366	  if (location === "/") {
367	    return (
368	      <>
369	        <GA4PageTracker />
370	        {isPwaStandalone() ? <AppLogin /> : <LandingPage />}
371	      </>
372	    );
373	  }
374	
375	  /* Tablet/desktop app screens keep a persistent chrome and deliberately skip
376	     PageTransition: that wrapper keys a motion.div on the location, so the frame
377	     inside it was torn down and rebuilt on every hop, and its mode="wait" exit
378	     spends 220ms on a blank screen before the destination even mounts. Here the
379	     frame + header + nav stay mounted and only the page slot swaps — the
380	     incoming page's own cascade is the transition. */
381	  if (deviceClass !== "mobile") {
382	    const chromeRoute = desktopChromeForLocation(location, merchantMode);
383	    if (chromeRoute) {
384	      return (
385	        <>
386	          <GA4PageTracker />
387	          {/* Outer boundary covers only the chrome's own chunk on cold load;
388	              once resolved it stays mounted, so navigation never suspends here
389	              and the frame cannot blink between screens. */}
390	          <Suspense fallback={<DesktopPageFallback />}>
391	            <DesktopChrome deviceClass={deviceClass} route={chromeRoute}>
392	              <Suspense fallback={<DesktopPageFallback />}>
393	                {/* Keyed on the screen, not the raw location, so the cascade
394	                    replays whenever the user lands on a different screen but a
395	                    one-shot param (?quick=1) or an id segment does not throw away
396	                    a screen the user is already on. */}
397	                <RouteTable
398	                  key={`${chromeRoute.vertical}/${chromeRoute.page}`}
399	                  location={location}
400	                  deviceClass={deviceClass}
401	                  merchantMode={merchantMode}
402	                />
403	              </Suspense>
404	            </DesktopChrome>
405	          </Suspense>
406	        </>
407	      );
408	    }
409	  }
410	
411	  return (
412	    <PageTransition>
413	      {/* Pin the Switch to the wrapper's location — matching from context would
414	          let the exiting page re-render as the destination during the exit
415	          animation (a double mount that eats one-shot params like ?quick=1). */}
416	      {(transitionLocation) => (
417	        <>
418	          <GA4PageTracker />
419	          <Suspense fallback={<PageLoader />}>
420	            <RouteTable
421	              location={transitionLocation}
422	              deviceClass={deviceClass}
423	              merchantMode={merchantMode}
424	            />
425	          </Suspense>
426	        </>
427	      )}
428	    </PageTransition>
429	  );
430	}
431	
432	function RouteTable({
433	  location,
434	  deviceClass,
435	  merchantMode,
436	}: {
437	  location: string;
438	  deviceClass: DeviceClass;
439	  merchantMode: MerchantMode;
440	}) {
441	  return (
442	        <Switch location={location}>
443	          <Route path="/"><LandingPage /></Route>
444	          <Route path="/info" component={InfoPage} />
445	          <Route path="/business-details" component={BusinessDetails} />
446	          <Route path="/check-email" component={CheckEmail} />
447	          <Route path="/confirm-email" component={ConfirmEmail} />
448	          <Route path="/login" component={Login} />
449	          <Route path="/signup" component={MerchantSignup} />
450	          <Route path="/accept-invite" component={AcceptInvite} />
451	          <Route path="/forgot-password" component={ForgotPassword} />
452	          <Route path="/reset-password" component={ResetPassword} />
453	          <Route path="/terminal">
454	            <ProtectedRoute tutorialPage="retail-terminal">
455	              {deviceClass === "mobile" ? <MerchantTerminalMobile /> : <DesktopRetailTerminal deviceClass={deviceClass} />}
456	            </ProtectedRoute>
457	          </Route>
458	          <Route path="/stack">
459	            <ProtectedRoute tutorialPage="retail-payment-stack">
460	              {deviceClass === "mobile" ? <PaymentStack /> : <DesktopRetailTerminal deviceClass={deviceClass} />}
461	            </ProtectedRoute>
462	          </Route>
463	          <Route path="/dashboard">
464	            <ProtectedRoute tutorialPage="retail-dashboard">
465	              {deviceClass === "mobile" ? <Dashboard /> : <DesktopRetailHome deviceClass={deviceClass} />}
466	            </ProtectedRoute>
467	          </Route>
468	          <Route path="/settings">
469	            <ProtectedRoute tutorialPage="settings">
470	              {deviceClass === "mobile" ? <Settings />
471	                : merchantMode === "property" ? <DesktopPropertySettings deviceClass={deviceClass} />
472	                : merchantMode === "trades" ? <DesktopTradesSettings deviceClass={deviceClass} />
473	                : <DesktopRetailSettings deviceClass={deviceClass} />}
474	            </ProtectedRoute>
475	          </Route>
476	          <Route path="/transactions">
477	            <ProtectedRoute tutorialPage="retail-transactions">
478	              {deviceClass === "mobile" ? <Transactions /> : <DesktopRetailAnalytics deviceClass={deviceClass} />}
479	            </ProtectedRoute>
480	          </Route>
481	          <Route path="/stock">
482	            <ProtectedRoute tutorialPage="retail-stock">
483	              {deviceClass === "mobile" ? <StockManagement /> : <DesktopRetailStock deviceClass={deviceClass} />}
484	            </ProtectedRoute>
485	          </Route>
486	          <Route path="/nfc">
487	            <ProtectedRoute tutorialPage="retail-nfc">
488	              {deviceClass === "mobile" ? <NFCPayment /> : <DesktopLegacyPage deviceClass={deviceClass} vertical="retail" page="terminal"><NFCPayment /></DesktopLegacyPage>}
489	            </ProtectedRoute>
490	          </Route>
491	          <Route path="/board-builder">
492	            <ProtectedRoute tutorialPage="payment-board-builder">
493	              {deviceClass === "mobile" ? <BoardBuilder /> : <DesktopLegacyPage deviceClass={deviceClass} vertical="retail" page="settings"><BoardBuilder /></DesktopLegacyPage>}
494	            </ProtectedRoute>
495	          </Route>
496	          <Route path="/smart-terminal" component={SmartTerminal} />
497	          {/* ── Property management section ── */}
498	          <Route path="/property">
499	            <ProtectedRoute tutorialPage="property-dashboard">
500	              {deviceClass === "mobile" ? <PropertyDashboard /> : <DesktopPropertyHome deviceClass={deviceClass} />}
501	            </ProtectedRoute>
502	          </Route>
503	          <Route path="/property/tenants">
504	            <ProtectedRoute tutorialPage="property-tenants">
505	              {deviceClass === "mobile" ? <TenantDirectory /> : <DesktopPropertyClients deviceClass={deviceClass} />}
506	            </ProtectedRoute>
507	          </Route>
508	          <Route path="/property/tenants/:id">
509	            <ProtectedRoute tutorialPage="property-tenant-profile">
510	              {deviceClass === "mobile" ? <TenantProfile /> : <DesktopLegacyPage deviceClass={deviceClass} vertical="property" page="directory"><TenantProfile /></DesktopLegacyPage>}
511	            </ProtectedRoute>
512	          </Route>
513	          <Route path="/property/analytics">
514	            <ProtectedRoute tutorialPage="property-analytics">
515	              {deviceClass === "mobile" ? <PropertyAnalytics /> : <DesktopPropertyAnalytics deviceClass={deviceClass} />}
516	            </ProtectedRoute>
517	          </Route>
518	          <Route path="/property/terminal">
519	            <ProtectedRoute tutorialPage="property-terminal">
520	              {deviceClass === "mobile" ? <PropertyTerminal /> : <DesktopPropertyTerminal deviceClass={deviceClass} />}
