552	            </ProtectedRoute>
553	          </Route>
554	          {/* Customer-facing quote acceptance → deposit/full payment, all on the
555	              branded Checkout card (quoteMode drives the animated 3-step flow). */}
556	          <Route path="/trades/quote/:token">{() => <Checkout sourceKind="quote-token" />}</Route>
557	          <Route path="/trades/recurring">
