560	            </ProtectedRoute>
561	          </Route>
562	          {/* Public rent/charge checkout — no auth required. Uses the shared
563	              branded Checkout page (same UI as retail) via the invoice token. */}
564	          <Route path="/r/:token">{() => <Checkout sourceKind="invoice-token" />}</Route>
565	          <Route path="/onboarding">
