cat > .tmp-repro/drift.ts <<'EOF'
import pg from "pg";
import { getTableConfig } from "drizzle-orm/pg-core";
import * as schema from "../shared/schema";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, max: 3 });

const dbCols = await pool.query<{ table_name: string; column_name: string }>(
  `select table_name, column_name from information_schema.columns where table_schema = 'public'`,
);
const byTable = new Map<string, Set<string>>();
for (const r of dbCols.rows) {
  if (!byTable.has(r.table_name)) byTable.set(r.table_name, new Set());
  byTable.get(r.table_name)!.add(r.column_name);
}

let missingTables: string[] = [];
let missingCols: Array<[string, string, string]> = [];

for (const [key, val] of Object.entries(schema)) {
  let cfg;
  try { cfg = getTableConfig(val as any); } catch { continue; }
  const live = byTable.get(cfg.name);
  if (!live) { missingTables.push(cfg.name); continue; }
  for (const col of cfg.columns) {
    if (!live.has(col.name)) {
      missingCols.push([cfg.name, col.name, col.getSQLType() + (col.notNull ? " NOT NULL" : "")]);
    }
  }
}

console.log("=== TABLES IN SCHEMA BUT NOT IN DB (" + missingTables.length + ") ===");
for (const t of missingTables) console.log("  " + t);
console.log("\n=== COLUMNS IN SCHEMA BUT NOT IN DB (" + missingCols.length + ") ===");
for (const [t, c, ty] of missingCols) console.log(`  ${t}.${c}  ${ty}`);
await pool.end();
process.exit(0);
EOF
