// Loads the real app as a signed-in merchant against the real dev API (no
// route mocks) and reports whether the shell ever gets past its loading state.
import { readFileSync } from "node:fs";
import { chromium } from "playwright";

const CHROMIUM_PATH =
  "/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium";
const BASE = "http://127.0.0.1:5000";
const TOKEN = readFileSync(new URL("./token22.txt", import.meta.url), "utf8").trim();

const VIEWPORTS = [
  { name: "mobile", width: 390, height: 844 },
  { name: "tablet", width: 1024, height: 768 },
  { name: "desktop", width: 1440, height: 900 },
];
const PATHS = ["/dashboard", "/terminal", "/transactions"];

const browser = await chromium.launch({
  executablePath: CHROMIUM_PATH,
  args: ["--no-sandbox", "--disable-dev-shm-usage"],
});

let failures = 0;

for (const vp of VIEWPORTS) {
  const context = await browser.newContext({
    viewport: { width: vp.width, height: vp.height },
    deviceScaleFactor: 1,
    isMobile: vp.name === "mobile",
    hasTouch: vp.name === "mobile",
  });
  await context.addInitScript((token) => {
    localStorage.setItem("authToken", token);
    localStorage.setItem("merchantId", "22");
    localStorage.setItem("taptMode", "retail");
  }, TOKEN);

  for (const path of PATHS) {
    const page = await context.newPage();
    const consoleErrors = [];
    const pageErrors = [];
    const pending = new Map();
    page.on("console", (m) => m.type() === "error" && consoleErrors.push(m.text().slice(0, 200)));
    page.on("pageerror", (e) => pageErrors.push(String(e.message).slice(0, 200)));
    page.on("request", (r) => pending.set(r, Date.now()));
    page.on("requestfinished", (r) => pending.delete(r));
    page.on("requestfailed", (r) => pending.delete(r));

    const t0 = Date.now();
    let verdict = "OK";
    let detail = "";
    try {
      await page.goto(`${BASE}${path}`, { waitUntil: "domcontentloaded", timeout: 20000 });
      // The app is "up" once the full-screen route loader is gone AND real
      // content exists. PageLoader carries data-testid="page-loader".
      await page.waitForFunction(
        () => {
          const loader = document.querySelector('[data-testid="page-loader"]');
          if (loader) return false;
          const root = document.getElementById("root");
          return !!root && root.innerText.trim().length > 0;
        },
        undefined,
        { timeout: 25000 },
      );
    } catch (err) {
      verdict = "STUCK";
      const stillLoading = await page
        .evaluate(() => !!document.querySelector('[data-testid="page-loader"]'))
        .catch(() => null);
      const stalled = [...pending.entries()]
        .filter(([, t]) => Date.now() - t > 3000)
        .map(([r]) => `${Date.now() - pending.get(r)}ms ${r.url().replace(BASE, "")}`);
      detail = `loaderVisible=${stillLoading} stalledRequests=${JSON.stringify(stalled.slice(0, 5))}`;
      failures++;
    }
    const ms = Date.now() - t0;
    const heading = await page
      .evaluate(() => document.querySelector("h1,h2,[class*=heading]")?.innerText?.slice(0, 40) ?? "")
      .catch(() => "");
    console.log(
      `[${vp.name.padEnd(7)}] ${path.padEnd(14)} ${verdict.padEnd(5)} ${String(ms).padStart(6)}ms  "${heading.replace(/\n/g, " ")}"`,
    );
    if (detail) console.log(`            ${detail}`);
    if (pageErrors.length) console.log(`            pageerror: ${pageErrors.slice(0, 3).join(" | ")}`);
    const realErrors = consoleErrors.filter((e) => !/favicon|manifest|sw\.js/i.test(e));
    if (realErrors.length) console.log(`            console: ${realErrors.slice(0, 3).join(" | ")}`);
    await page.close();
  }
  await context.close();
}

await browser.close();
console.log(failures === 0 ? "\nRESULT: all viewports loaded" : `\nRESULT: ${failures} stuck`);
process.exit(failures === 0 ? 0 : 1);

