input.content:
/**
 * Finds Express route handlers where an async rejection can escape.
 *
 * Express 4 does not forward a rejected handler promise to the error handler,
 * so an unguarded `await` that throws leaves the request open forever and the
 * client hangs. Also flags catch blocks that never answer the request, which
 * produces the same hang despite looking guarded.
 */
import ts from "typescript";
import { readFileSync } from "node:fs";

const FILES = process.argv.slice(2);
const METHODS = new Set(["get", "post", "put", "patch", "delete", "all", "use"]);

type Finding = {
  file: string;
  method: string;
  path: string;
  line: number;
  unguardedAwaits: Array<{ line: number; text: string }>;
  silentCatches: Array<{ line: number }>;
};

const findings: Finding[] = [];
let totalAsyncHandlers = 0;

for (const file of FILES) {
  const src = ts.createSourceFile(
    file,
    readFileSync(file, "utf8"),
    ts.ScriptTarget.Latest,
    true,
  );
  const lineOf = (n: ts.Node) => src.getLineAndCharacterOfPosition(n.getStart(src)).line + 1;

  function isAsyncFn(n: ts.Node): n is ts.ArrowFunction | ts.FunctionExpression {
    return (
      (ts.isArrowFunction(n) || ts.isFunctionExpression(n)) &&
      !!n.modifiers?.some((m) => m.kind === ts.SyntaxKind.AsyncKeyword)
    );
  }

  // True if the block contains a call that answers the request: res.json,
  // res.status(..).json, res.send, res.end, res.redirect, next(...) — next
  // hands off to the global error handler, which does respond.
  function answersRequest(node: ts.Node): boolean {
    let found = false;
    const visit = (n: ts.Node) => {
      if (found) return;
      if (ts.isCallExpression(n)) {
        const t = n.expression.getText(src);
        if (/^(res|response)\s*\.\s*(json|send|end|redirect|sendStatus|sendFile|write|render|pipe)/.test(t)) found = true;
        if (/^(res|response)\s*\.\s*status\([^)]*\)\s*\.\s*(json|send|end)/.test(t)) found = true;
        if (/^next$/.test(t) && n.arguments.length > 0) found = true;
        // helper wrappers that reply on the caller's behalf
        if (/^(fulfillJson|sendError|respond|replyError|handleError)/.test(t)) found = true;
      }
      ts.forEachChild(n, visit);
    };
    visit(node);
    return found;
  }

  function analyzeHandler(fn: ts.ArrowFunction | ts.FunctionExpression, finding: Finding) {
    // Walk the handler's own async scope. `guarded` means we sit inside a try
    // that has a catch clause, so a rejection there cannot escape.
    const walk = (n: ts.Node, guarded: boolean) => {
      if (ts.isTryStatement(n)) {
        const hasCatch = !!n.catchClause;
        walk(n.tryBlock, guarded || hasCatch);
        if (n.catchClause) {
          // A throw inside catch escapes unless an outer try guards it.
          walk(n.catchClause.block, guarded);
          if (!answersRequest(n.catchClause.block) && !hasReThrow(n.catchClause.block)) {
            finding.silentCatches.push({ line: lineOf(n.catchClause) });
          }
        }
        if (n.finallyBlock) walk(n.finallyBlock, guarded);
        return;
      }
      // Nested functions have their own rejection scope; skip them here.
      if (n !== fn && (ts.isArrowFunction(n) || ts.isFunctionExpression(n) || ts.isFunctionDeclaration(n) || ts.isMethodDeclaration(n))) {
        return;
      }
      if (ts.isAwaitExpression(n) && !guarded) {
        finding.unguardedAwaits.push({
          line: lineOf(n),
          text: n.getText(src).replace(/\s+/g, " ").slice(0, 90),
        });
      }
      ts.forEachChild(n, (c) => walk(c, guarded));
    };
    if (fn.body) walk(fn.body, false);
  }

  function hasReThrow(block: ts.Node): boolean {
    let found = false;
    const visit = (n: ts.Node) => {
      if (found) return;
      if (ts.isThrowStatement(n)) found = true;
      ts.forEachChild(n, visit);
    };
    visit(block);
    return found;
  }

  const visit = (node: ts.Node) => {
    if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
      const obj = node.expression.expression.getText(src);
      const method = node.expression.name.getText(src);
      if ((obj === "app" || obj === "router") && METHODS.has(method)) {
        const first = node.arguments[0];
        const routePath =
          first && ts.isStringLiteral(first) ? first.text : first ? first.getText(src).slice(0, 40) : "(none)";
        for (const arg of node.arguments.slice(1)) {
          if (!isAsyncFn(arg)) continue;
          totalAsyncHandlers++;
          const finding: Finding = {
            file,
            method: method.toUpperCase(),
            path: routePath,
            line: lineOf(node),
            unguardedAwaits: [],
            silentCatches: [],
          };
          analyzeHandler(arg, finding);
          if (finding.unguardedAwaits.length || finding.silentCatches.length) findings.push(finding);
        }
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(src);
}

const hangRisk = findings.filter((f) => f.unguardedAwaits.length > 0);
const silentOnly = findings.filter((f) => !f.unguardedAwaits.length && f.silentCatches.length > 0);

console.log(`async route handlers scanned: ${totalAsyncHandlers}`);
console.log(`handlers with an unguarded await (can hang the client): ${hangRisk.length}`);
console.log(`handlers whose catch never answers (also hangs): ${silentOnly.length}\n`);

console.log("================ UNGUARDED AWAIT (HANG RISK) ================");
for (const f of hangRisk.sort((a, b) => a.line - b.line)) {
  console.log(`\n${f.method} ${f.path}   [${f.file}:${f.line}]  ${f.unguardedAwaits.length} unguarded await(s)`);
  for (const a of f.unguardedAwaits.slice(0, 3)) console.log(`   L${a.line}: ${a.text}`);
  if (f.unguardedAwaits.length > 3) console.log(`   … +${f.unguardedAwaits.length - 3} more`);
}

if (silentOnly.length) {
  console.log("\n================ CATCH WITHOUT A RESPONSE ================");
  for (const f of silentOnly.sort((a, b) => a.line - b.line)) {
    console.log(`${f.method} ${f.path}   [${f.file}:${f.line}]  catch at L${f.silentCatches.map((c) => c.line).join(", L")}`);
  }
}

