];

// Added unconditionally at boot by server/index.ts, so they are expected to be
// absent until the app next starts. Anything else missing is a real failure.
const EXPECTED_STILL_MISSING = new Set([
  "merchants.business_description",
  "merchants.website_url",
  "merchants.estimated_annual_turnover",
]);

function strip(sql: string): string {
  return sql
    .split("\n")
    .filter((line) => !/^\s*(BEGIN|COMMIT|ROLLBACK)\s*;\s*$/.test(line))
    .join("\n");
}

async function measureDrift(exec: (q: string) => Promise<any>) {
  const res = await exec(
