    byTable.get(r.table_name)!.add(r.column_name);
  }
  const tables: string[] = [];
  const columns: string[] = [];
  for (const val of Object.values(schema)) {
    let cfg;
    try { cfg = getTableConfig(val as any); } catch { continue; }
    const live = byTable.get(cfg.name);
    if (!live) { tables.push(cfg.name); continue; }
    for (const c of cfg.columns) if (!live.has(c.name)) columns.push(`${cfg.name}.${c.name}`);
  }
  return { tables, columns };
}

const client = new pg.Client({ connectionString: url });
await client.connect();
const exec = (q: string) => client.query(q);

let committed = false;
try {
  const before = await measureDrift(exec);
  console.log(`BEFORE  missing tables=${before.tables.length} columns=${before.columns.length}`);

  await exec("BEGIN");
  for (const f of FILES) {
    const t0 = Date.now();
    await exec(strip(readFileSync(f, "utf8")));
    console.log(`  applied ${f}  (${Date.now() - t0}ms)`);
  }

  const after = await measureDrift(exec);
  const unexpected = after.columns.filter((c) => !EXPECTED_STILL_MISSING.has(c));
  console.log(`AFTER   missing tables=${after.tables.length} columns=${after.columns.length}`);

  // Gate the commit on the schema being exactly what we predicted.
  if (after.tables.length > 0) throw new Error(`tables still missing: ${after.tables.join(", ")}`);
  if (unexpected.length > 0) throw new Error(`unexpected columns still missing: ${unexpected.join(", ")}`);

  const owners = await exec(
    `select (select count(*)::int from merchants where password_hash is not null) as with_pw,
            (select count(*)::int from merchants m where m.password_hash is not null
               and not exists (select 1 from users u where u.merchant_id=m.id and u.role='owner')) as missing_owner,
            (select count(*)::int from merchant_subscriptions where plan_id is null) as subs_without_plan`,
  );
  const { with_pw, missing_owner, subs_without_plan } = owners.rows[0];
  console.log(`  merchants with password=${with_pw} missing owner=${missing_owner} subs without plan=${subs_without_plan}`);
  if (missing_owner !== 0) throw new Error("a password-enabled merchant has no owner identity");
  if (subs_without_plan !== 0) throw new Error("a subscription row has no plan");

  await exec("COMMIT");
