  await exec("ROLLBACK").catch(() => {});
  console.error("\nROLLED BACK — production unchanged. Reason:", (err as Error).message);
  process.exitCode = 1;
} finally {
  await client.end();
}

if (committed) {
  const verify = new pg.Client({ connectionString: url });
  await verify.connect();
  const post = await measureDrift((q) => verify.query(q));
  const subs = await verify.query(
    `select plan_id, seat_limit, price_cents, status, count(*)::int n from merchant_subscriptions group by 1,2,3,4 order by 1`,
  );
  const users = await verify.query(`select role, status, count(*)::int n from users group by 1,2`);
  await verify.end();
  console.log(`\nVERIFIED on a fresh connection:`);
  console.log(`  missing tables=${post.tables.length} columns=${post.columns.length} (${post.columns.join(", ") || "none"})`);
  console.log(`  subscriptions: ${JSON.stringify(subs.rows)}`);
  console.log(`  users: ${JSON.stringify(users.rows)}`);
}
process.exit(process.exitCode ?? 0);

